tSpecial(0);EnsureWindow(ViewMode.Inventory);showHangar=true;inventorySelection=2;inventoryScroll=Array.IndexOf(DemoWorld.InventoryIds.Where(id=>world.ItemCount(id,true)>.001f).ToArray(),"sp_ghost");break;case 15:var item=itemHits.First(h=>h.Id=="sp_ghost");TestDrag(item.Rect.Center.ToVector2(),new(1160,425));break;case 16:Check(world.Player.Special[1].ModuleId=="sp_ghost","Drag inventory to capital fitting socket");desktop.RemoveAll(x=>x.Kind==ViewMode.Inventory);break;case 17:TestPointer(new(w.X+w.Width-90,w.Y+405),right:ButtonState.Pressed);TestPointer(new(w.X+w.Width-90,w.Y+405));Check(context&&popupActions.Any(a=>a.Label=="Toggle online"),"Capital right-click context menu");break;case 18:Click("Toggle online");break;case 19:Check(!world.Player.Special[1].Online,"Capital context online action");world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Player.Special[1].ModuleId=="sp_ghost"&&!loaded.Player.Special[1].Online,"Capital UI fit save/load");break;case 20:Click("JUMP NETWORK");break;case 21:Click("CONTRACT REMOTE BEACON");Check(world.JumpBeacons.Count==0,"No destination contract refused");break;case 22:Click("CLONING");break;case 23:Click("INSTALL STATION JUMP CLONE");break;case 24:Check(world.JumpClones.Count==1,"Station clone installed through UI");Click("FITTING");break;case 25:Click("MODULE MARKET");break;case 26:Check(desktop.Last().Kind==ViewMode.Market,"Capital item opens market");break;case 28:Console.WriteLine($"{specialUiChecks} special graphical interaction checks passed.");break;}oldMouse=Mouse.GetState();}
